-- Read-only catalog gate. No application RPC is invoked; run only in verified staging.
WITH reviewed(name) AS (SELECT unnest(ARRAY['audit_events','case_pick_allocations','conversation_members','conversations','customer_contacts','customer_items','customer_review_manifest_approvals','customer_review_manifests','customer_ship_tos','customers','documents','exceptions','integration_customer_mappings','integration_import_batches','integration_item_mappings','integration_ship_to_mappings','inventory_lots','inventory_transaction_lines','inventory_transactions','item_identifiers','item_packaging_instructions','item_weight_bands','items','message_reads','messages','order_lines','orders','organizations','pallet_case_assignments','pallet_cases','pallets','production_case_weight_events','production_cases','production_lots','production_run_consumptions','production_run_outputs','production_runs','production_stations','production_weight_readings','profiles','shipment_contents','shipments','sps_order_exceptions','sps_staged_order_lines','sps_staged_orders','vendor_items','vendors','warehouses']::text[])),
sps(name) AS (VALUES ('sps_staged_orders'),('sps_staged_order_lines'),('sps_order_exceptions'),('integration_customer_mappings'),('integration_ship_to_mappings'),('integration_item_mappings')),
rpcs(signature,owner_name) AS (VALUES
 ('public.promote_sps_staged_order(uuid)','lucid_sps_promoter'),
 ('public.create_lucid_qa_order(text,text,text,text,text,numeric,text)','lucid_sps_promoter'),
 ('public.start_lucid_production(uuid)','lucid_order_operator'),
 ('public.complete_lucid_production(uuid)','lucid_order_operator')),
checks(label,passed,detail) AS (
 SELECT '48-table inventory',
   (SELECT array_agg(c.relname::text ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r')
    = (SELECT array_agg(name ORDER BY name) FROM reviewed), 'Exact reviewed application-table allowlist'
 UNION ALL SELECT 'RLS enabled: '||r.name,coalesce(c.relrowsecurity,false),'RLS must remain enabled'
  FROM reviewed r LEFT JOIN pg_class c ON c.oid=to_regclass('public.'||r.name)
 UNION ALL SELECT '030 source identity',EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='sps_staged_orders' AND column_name='source_document_key'),'Requires 030 foundation'
 UNION ALL SELECT 'SPS write-role trigger: '||s.name,
  EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid=to_regclass('public.'||s.name) AND NOT t.tgisinternal AND t.tgenabled<>'D' AND p.proname='assert_lucid_sps_write_role'),'Role gate retained independently of base ACL'
 FROM sps s

 UNION ALL SELECT 'SPS authenticated row privileges: '||s.name,bool_and(has_table_privilege('authenticated',to_regclass('public.'||s.name),p.privilege)),'SELECT INSERT UPDATE DELETE only' FROM sps s CROSS JOIN (VALUES('SELECT'),('INSERT'),('UPDATE'),('DELETE')) p(privilege) GROUP BY s.name
 UNION ALL SELECT 'SPS anon/service denial: '||s.name,NOT EXISTS(SELECT 1 FROM (VALUES('anon'),('service_role')) r(name) CROSS JOIN (VALUES('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN')) p(privilege) WHERE has_table_privilege(r.name,to_regclass('public.'||s.name),p.privilege)),'No unproven service persistence' FROM sps s
 UNION ALL SELECT 'SPS PUBLIC denial: '||s.name,NOT EXISTS(SELECT 1 FROM pg_class c,LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid=to_regclass('public.'||s.name) AND a.grantee=0),'No PUBLIC table ACL' FROM sps s
 UNION ALL SELECT 'Operational browser read only: '||t.name,
 has_table_privilege('authenticated',to_regclass('public.'||t.name),'SELECT') AND NOT EXISTS(SELECT 1 FROM (VALUES('INSERT'),('UPDATE'),('DELETE')) p(v) WHERE has_table_privilege('authenticated',to_regclass('public.'||t.name),p.v)) AND NOT has_any_column_privilege('authenticated',to_regclass('public.'||t.name),'INSERT,UPDATE,REFERENCES'),'No direct order or audit forging'
 FROM (VALUES('orders'),('order_lines'),('audit_events')) t(name)
 UNION ALL SELECT 'Unsafe browser privileges: '||r.name,NOT EXISTS(SELECT 1 FROM (VALUES('anon'),('authenticated')) x(role_name) CROSS JOIN (VALUES('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN')) p(v) WHERE has_table_privilege(x.role_name,to_regclass('public.'||r.name),p.v)),'Effective privileges include inherited PUBLIC grants' FROM reviewed r
 UNION ALL SELECT 'Private role attributes: '||r.name,coalesce(NOT(p.rolcanlogin OR p.rolsuper OR p.rolcreatedb OR p.rolcreaterole OR p.rolinherit OR p.rolbypassrls),false),'No login, administration, inheritance or RLS bypass' FROM (VALUES('lucid_sps_promoter'),('lucid_order_operator')) r(name) LEFT JOIN pg_roles p ON p.rolname=r.name
 UNION ALL SELECT 'No private memberships with execution access',NOT EXISTS(select 1 from pg_catalog.pg_auth_members m
   join pg_catalog.pg_roles r on r.oid=m.roleid or r.oid=m.member
   where r.rolname in ('lucid_sps_promoter','lucid_order_operator')
   and not coalesce((m.roleid=r.oid
     and m.member=(select oid from pg_catalog.pg_roles where rolname='postgres')
     and m.grantor=(select oid from pg_catalog.pg_roles where oid=10 and rolname='supabase_admin' and rolsuper)
     and m.admin_option and not m.inherit_option and not m.set_option),false)) AND NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname IN ('lucid_sps_promoter','lucid_order_operator') AND (pg_has_role('postgres',r.oid,'SET') OR pg_has_role('postgres',r.oid,'USAGE'))),'Only mandatory Supabase-bootstrap ADMIN-only creator grant may remain; no app, self-granted, SET or INHERIT path'
 UNION ALL SELECT 'No private table ownership',NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_roles r ON r.oid=c.relowner WHERE r.rolname IN ('lucid_sps_promoter','lucid_order_operator') AND c.relkind IN ('r','p','S')),'Neither private role owns tables or sequences'
 UNION ALL SELECT 'No residual schema CREATE',NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname IN ('anon','authenticated','lucid_sps_promoter','lucid_order_operator') AND has_schema_privilege(r.oid,'public','CREATE')),'No browser or private bootstrap CREATE'
 UNION ALL SELECT 'RPC security: '||r.signature,coalesce(p.prosecdef AND p.proowner=(SELECT oid FROM pg_roles WHERE rolname=r.owner_name) AND EXISTS(SELECT 1 FROM unnest(p.proconfig) cfg WHERE cfg IN ('search_path=""','search_path=')),false),'Exact private owner, SECURITY DEFINER, empty search_path' FROM rpcs r LEFT JOIN pg_proc p ON p.oid=to_regprocedure(r.signature)
 UNION ALL SELECT 'RPC execute: '||r.signature,has_function_privilege('authenticated',to_regprocedure(r.signature),'EXECUTE') AND NOT has_function_privilege('anon',to_regprocedure(r.signature),'EXECUTE') AND NOT has_function_privilege('service_role',to_regprocedure(r.signature),'EXECUTE') AND NOT EXISTS(SELECT 1 FROM pg_proc p,LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=to_regprocedure(r.signature) AND a.grantee=0 AND a.privilege_type='EXECUTE'),'Authenticated entry only; private owner remains owner' FROM rpcs r
 UNION ALL SELECT 'Future table defaults',NOT EXISTS(SELECT 1 FROM pg_default_acl d JOIN pg_namespace n ON n.oid=d.defaclnamespace,LATERAL aclexplode(d.defaclacl) a WHERE n.nspname='public' AND d.defaclrole=(SELECT oid FROM pg_roles WHERE rolname='postgres') AND d.defaclobjtype='r' AND (a.grantee=0 OR a.grantee IN (SELECT oid FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')))),'Only postgres/public/table defaults reviewed'
 UNION ALL SELECT 'Operator status-only UPDATE',has_column_privilege('lucid_order_operator','public.orders','status','UPDATE') AND NOT has_table_privilege('lucid_order_operator','public.orders','UPDATE') AND NOT EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid='public.orders'::regclass AND a.attnum>0 AND NOT a.attisdropped AND a.attname<>'status' AND has_column_privilege('lucid_order_operator',a.attrelid,a.attnum,'UPDATE')),'Only orders.status can be updated'
 UNION ALL SELECT 'Private operational INSERT boundary',has_table_privilege('lucid_sps_promoter','public.orders','INSERT') AND has_table_privilege('lucid_sps_promoter','public.order_lines','INSERT') AND has_table_privilege('lucid_sps_promoter','public.audit_events','INSERT') AND has_table_privilege('lucid_order_operator','public.audit_events','INSERT') AND NOT has_table_privilege('lucid_order_operator','public.orders','INSERT') AND NOT has_table_privilege('lucid_order_operator','public.order_lines','INSERT'),'Fixed RPC constructors, not generic write endpoints'
 UNION ALL SELECT 'Promoter metadata-only UPDATE',NOT has_table_privilege('lucid_sps_promoter','public.sps_staged_orders','UPDATE') AND NOT EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid='public.sps_staged_orders'::regclass AND a.attnum>0 AND NOT a.attisdropped AND has_column_privilege('lucid_sps_promoter',a.attrelid,a.attnum,'UPDATE') IS DISTINCT FROM (a.attname IN ('review_status','promoted_order_id','approved_by','approved_at'))),'No source-payload write privilege'
 UNION ALL SELECT 'New security trigger: '||x.name,EXISTS(SELECT 1 FROM pg_trigger WHERE tgname=x.name AND NOT tgisinternal AND tgenabled<>'D'),'Enabled DB guard, independent of HTTP role checks' FROM (VALUES('protect_lucid_sps_promotion_metadata'),('protect_lucid_sps_exception_price_authority'),('protect_lucid_sps_mapping_price_authority'),('protect_lucid_sps_line_price_authority')) x(name)
 UNION ALL SELECT 'Guard execute denied: '||x.signature,NOT EXISTS(SELECT 1 FROM (VALUES('anon'),('authenticated'),('service_role')) r(name) WHERE has_function_privilege(r.name,to_regprocedure(x.signature),'EXECUTE')),'Trigger invocation remains available; direct client invocation denied' FROM (VALUES('public.protect_lucid_sps_promotion_metadata()'),('public.protect_lucid_sps_price_authority()'),('public.protect_lucid_promoted_sps_source()')) x(signature)
 UNION ALL SELECT 'OLD and NEW parent guard',coalesce((SELECT prosrc LIKE '%OLD.staged_order_id%' AND prosrc LIKE '%NEW.staged_order_id%' FROM pg_proc WHERE oid=to_regprocedure('public.protect_lucid_promoted_sps_source()')),false),'Structural check; rollback behavioral tests still required'
 UNION ALL SELECT 'Promotion business guard definitions',coalesce((SELECT prosrc LIKE '%for update%' AND prosrc LIKE '%actor.role not in%' AND prosrc LIKE '%o.active%' AND prosrc LIKE '%document_type=''860''%' AND prosrc LIKE '%quantity<=0%' AND prosrc LIKE '%Ambiguous exact%' AND prosrc LIKE '%l.sps_uom is distinct from%' AND prosrc LIKE '%s.organization_id=actor.organization_id%' AND prosrc LIKE '%select existing_id,true%' AND prosrc LIKE '%reviewer.role in%' AND prosrc LIKE '%e.status=''open''%' FROM pg_proc WHERE oid=to_regprocedure('public.promote_sps_staged_order(uuid)')),false),'Structural markers do not claim behavioral execution'
 UNION ALL SELECT 'QA Admin gate',coalesce((SELECT prosrc LIKE '%actor.role<>''lucid_admin''%' AND prosrc LIKE '%QA-%' FROM pg_proc WHERE oid=to_regprocedure('public.create_lucid_qa_order(text,text,text,text,text,numeric,text)')),false),'Admin-only QA provenance retained'

 UNION ALL SELECT 'Price authority definition',coalesce((SELECT prosrc LIKE '%actor.role=''office''%' AND prosrc LIKE '%Only leadership or Lucid Admin%' AND prosrc LIKE '%NEW.resolved_by:=actor.id%' AND prosrc LIKE '%source purchase price%' FROM pg_proc WHERE oid=to_regprocedure('public.protect_lucid_sps_price_authority()')),false),'Price finalization is enforced beneath direct authenticated DML'
 UNION ALL SELECT 'Promotion metadata definition',coalesce((SELECT prosrc LIKE '%current_user <> ''lucid_sps_promoter''%' AND prosrc LIKE '%NEW.promoted_order_id is distinct from OLD.promoted_order_id%' AND prosrc LIKE '%NEW.approved_by%' FROM pg_proc WHERE oid=to_regprocedure('public.protect_lucid_sps_promotion_metadata()')),false),'Normal reviewers cannot forge privileged metadata'
 UNION ALL SELECT 'Dependency reads for private owners',has_table_privilege('lucid_sps_promoter','public.order_lines','SELECT') AND has_table_privilege('lucid_order_operator','public.production_cases','SELECT') AND has_table_privilege('lucid_order_operator','public.customers','SELECT') AND has_table_privilege('lucid_order_operator','public.customer_ship_tos','SELECT'),'Existing scope triggers and completion checks must remain executable'
 UNION ALL SELECT 'No unbounded global table defaults',NOT EXISTS(SELECT 1 FROM pg_default_acl d,LATERAL aclexplode(d.defaclacl) a WHERE d.defaclrole=(SELECT oid FROM pg_roles WHERE rolname='postgres') AND d.defaclnamespace=0 AND d.defaclobjtype='r' AND (a.grantee=0 OR a.grantee IN (SELECT oid FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role')))),'A schema-level REVOKE cannot undo global default grants; outside approved scope'
 UNION ALL SELECT 'SPS RLS same-org policy: '||s.name,EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid=to_regclass('public.'||s.name) AND p.polcmd='*' AND 0=ANY(p.polroles) AND pg_get_expr(p.polqual,p.polrelid) LIKE '%organization_id = current_org_id()%' AND pg_get_expr(p.polwithcheck,p.polrelid) LIKE '%organization_id = current_org_id()%'),'Private owners remain subject to PUBLIC same-org RLS' FROM sps s
 UNION ALL SELECT 'Operational anon/service denial: '||t.name,NOT EXISTS(SELECT 1 FROM (VALUES('anon'),('service_role')) r(name) CROSS JOIN (VALUES('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER'),('MAINTAIN')) p(v) WHERE has_table_privilege(r.name,to_regclass('public.'||t.name),p.v)),'No operational persistence via ordinary or service clients' FROM (VALUES('orders'),('order_lines'),('audit_events')) t(name)
 UNION ALL SELECT 'All RPC actor and organization guards: '||r.signature,coalesce(p.prosrc LIKE '%p.id=public.lucid_request_actor_id() and p.active and o.active%' AND p.prosrc LIKE '%actor.organization_id%',false),'Definitions retain active actor, active organization and derived organization' FROM rpcs r LEFT JOIN pg_proc p ON p.oid=to_regprocedure(r.signature)
 UNION ALL SELECT 'Private owners have no auth USAGE',NOT EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname IN ('lucid_sps_promoter','lucid_order_operator') AND has_schema_privilege(r.oid,'auth','USAGE')),'No direct, inherited or PUBLIC auth access'
 UNION ALL SELECT 'Actor helper exact definition',coalesce((SELECT p.pronargs=0 AND p.prorettype='uuid'::regtype AND p.prosecdef AND p.provolatile='s' AND p.proowner=(SELECT oid FROM pg_roles WHERE rolname='postgres') AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND p.proconfig=ARRAY['search_path=""']::text[] AND md5(p.prosrc)='352a2d96cda56814b9d8e509dfa0e375' FROM pg_proc p WHERE p.oid=to_regprocedure('public.lucid_request_actor_id()')),false),'Zero arguments; only auth.uid read/null rejection; exact approved helper body'
 UNION ALL SELECT 'Actor helper no overloads',(SELECT count(*)=1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='lucid_request_actor_id'),'No caller-supplied identity signature'
 UNION ALL SELECT 'Actor helper exact EXECUTE ACL',coalesce((SELECT array_agg(pg_get_userbyid(a.grantee)::text ORDER BY pg_get_userbyid(a.grantee)::text)=ARRAY['authenticated','lucid_order_operator','lucid_sps_promoter','postgres']::text[] AND bool_and(a.privilege_type='EXECUTE' AND (NOT a.is_grantable OR a.grantee=p.proowner)) FROM pg_proc p,LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=to_regprocedure('public.lucid_request_actor_id()') GROUP BY p.proowner),false),'No PUBLIC/anon/service access or delegated helper EXECUTE'
 UNION ALL SELECT 'Private/helper actor dependencies',NOT EXISTS(SELECT 1 FROM rpcs r JOIN pg_proc p ON p.oid=to_regprocedure(r.signature) WHERE p.prosrc LIKE '%auth.%' OR p.prosrc NOT LIKE '%public.lucid_request_actor_id()%'),'Operational private-owner bodies do not access auth schema'
 UNION ALL SELECT 'SPS trigger uses actor helper',coalesce((SELECT NOT p.prosecdef AND p.prosrc LIKE '%p.id=public.lucid_request_actor_id()%' AND p.prosrc NOT LIKE '%auth.%' AND p.prosrc LIKE '%actor.role not in%' AND EXISTS(SELECT 1 FROM unnest(p.proconfig) cfg WHERE cfg='search_path=""') FROM pg_proc p WHERE p.oid=to_regprocedure('public.assert_lucid_sps_write_role()')),false),'Same role/org gate; invoker has no direct Auth dependency'
 UNION ALL SELECT 'Audit RLS uses same actor helper',EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid='public.audit_events'::regclass AND p.polname='audit insert own actor' AND p.polcmd='a' AND p.polroles=ARRAY[0]::oid[] AND pg_get_expr(p.polwithcheck,p.polrelid) LIKE '%organization_id = current_org_id()%' AND pg_get_expr(p.polwithcheck,p.polrelid) LIKE '%actor_id = lucid_request_actor_id()%'),'Same-org/actual-actor requirement retained; no direct auth dependency'

)
SELECT jsonb_build_object('checks',jsonb_agg(jsonb_build_object('check',label,'result',CASE WHEN coalesce(passed,false) THEN 'PASS' ELSE 'FAIL' END,'detail',detail) ORDER BY label),
 'failed_checks',count(*) FILTER(WHERE NOT coalesce(passed,false)),
 'release_decision',CASE WHEN bool_and(coalesce(passed,false)) THEN 'POST-APPLY VERIFICATION PASS' ELSE 'POST-APPLY VERIFICATION FAIL' END) AS verification
FROM checks;
